    if (k == n) { cb(p); return; }
    for (int v = 0; v < n; ++v) {
        bool used = false;
        for (int i = 0; i < k; ++i) if (p[i] == v) used = true;
        if (used) continue;
        p[k] = v;
        perms(n, p, k + 1, cb);
    }
}

int main() {
    int a[5][5];
